VNUM_SETS = {}
for _id, (_name, _parts, _grades) in SETS.items():
	for _label, _vnums in _parts:
		for _v in _vnums:
			VNUM_SETS.setdefault(_v, []).append(_id)


def GradeLines(setId, parts):
	"""the bonus lines of a set's grade for that many parts (the highest grade not above it)"""
	if setId >= LEGACY_BASE:
		return LEGACY_LINES if parts >= 2 else ()
	if not SETS.has_key(setId):
		return ()
	grades = SETS[setId][2]
	for g in xrange(parts, 1, -1):
		if grades.has_key(g):
			return grades[g]
	return ()


def AffectDescription(value):
	"""the affect bar's tooltip of affect 545 (uiaffectbar.py): lines split by ;"""
	value = int(value)
	setId, parts = value // 10, value % 10
	if setId >= LEGACY_BASE or not SETS.has_key(setId):
		lines = ["Bonus zestawu kostium\xf3w", "Za\xb3o\xbfone cz\xea\x9cci zestawu: %d/2" % parts]
	else:
		name, partList, grades = SETS[setId]
		lines = ["Zestaw: " + name, "Za\xb3o\xbfone cz\xea\x9cci zestawu: %d/%d" % (parts, len(partList))]
	lines += list(GradeLines(setId, parts))
	return ";".join(lines)
